    def __init__(self,PanelID,MeterID,Node,meter_info) :
        self.meter_info=meter_info
        self.DeviceValues = {
          "PanelID": PanelID,
          "MeterID": MeterID,
          "Node":  Node
        }


     

    def getDeviceValues(self):
        self.DeviceValues['time']=int(time()*1000)
        return self.DeviceValues

